    edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]

    graph = [[] for _ in range(n + 1)]
    for a, b, c in edges:
        graph[a].append((b, c))
        graph[b].append((a, c))

    ok = float("inf")
    minng = 2000000001

    for i in range(1, n + 1):
        graph[i].sort(key=lambda x: x[1])
        if ok > graph[i][0][1]:
            ok = graph[i][0][1]
        if len(graph[i]) >= 2 and graph[i][0][1] + graph[i][1][1] < minng:
            minng = graph[i][0][1] + graph[i][1][1]

    ng = minng + 1

    def solve(mid):
        visited = [-1 for _ in range(n + 1)]

        for i in range(1, n + 1):
            if visited[i] != -1:
                continue

            visited[i] = 0
            que = [i]
            while que:
                nque = []
                while que:
                    v = que.pop()
                    for nv, c in graph[v]:
                        if c < mid:
                            break
                        if visited[nv] == visited[v]:
                            return False
                        if visited[nv] == -1:
                            visited[nv] = visited[v] ^ 1
                            nque.append(nv)
                que = nque

        return True

    while abs(ok - ng) > 1:
        mid = (ok + ng) // 2
        if solve(mid):
            ok = mid
        else:
            ng = mid

    print(ok)

