    edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]
    return n, m, edges

def has_valid_path(graph, mid):
    n = len(graph)
    visited = [-1] * (n + 1)

    def dfs(node, parent_color):
        if visited[node] != -1:
            return visited[node] == parent_color
        visited[node] = 1 - parent_color

        for neighbor, cost in graph[node]:
            if cost >= mid and not dfs(neighbor, 1 - parent_color):
                return False
        return True

    for i in range(1, n + 1):
        if visited[i] == -1 and not dfs(i, 0):
            return False
    return True

def binary_search_min_cost(n, m, edges):
    graph = [[] for _ in range(n + 1)]

    for a, b, c in edges:
        graph[a].append((b, c))
        graph[b].append((a, c))

    left, right = min(e[2] for e in edges), max(e[2] for e in edges)
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if has_valid_path(graph, mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

