for a, b, c in abc:
    graph[a].append((b, c))
    graph[b].append((a, c))

# Initialize variables
ok = float("inf")
minng = 2000000001

# Sort edges by weight and find the minimum cost of any edge
for i in range(1, n+1):
    graph[i].sort(key=lambda x: x[1])
    if ok > graph[i][0][1]:
        ok = graph[i][0][1]

    if len(graph[i]) >= 2:
        temp = graph[i][0][1] + graph[i][1][1]
        if minng > temp:
            minng = temp

# Binary search for the optimal threshold
ng = minng + 1

while abs(ok-ng) > 1:
    mid = (ok+ng)//2

    # Function to check if there is a path with cost <= mid
    def solve(mid):
        visited = [-1 for i in range(n+1)]
        que = [i for i in range(1, n+1) if graph[i] and graph[i][0][1] >= mid]

        while que:
            current_node = que.pop()
            for next_node, cost in graph[current_node]:
                if cost >= mid and visited[next_node] == -1:
                    visited[next_node] = visited[current_node] ^ 1
                    que.append(next_node)

        return all(v != -1 for v in visited[1:])

    # Adjust search range based on the solution
    if solve(mid):
        ok = mid
    else:
        ng = mid

