    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    i = 2
    mp = []
    for _ in range(m):
        mp.append(int(data[i]))
        i += 1

    abc = []
    for a, b, c in zip(mp[:-2], mp[1:-1], mp[2:]):
        abc.append((a, b, c))

    graph = [[] for i in range(n+1)]

    for a, b, c in abc:
        graph[a].append((b, c))
        graph[b].append((a, c))

    ok = float("inf")

    for i in range(1, n+1):
        graph[i].sort(key=lambda x: x[1])
        if ok > graph[i][0][1]:
            ok = graph[i][0][1]

        if len(graph[i]) >= 2:
            temp = graph[i][0][1] + graph[i][1][1]
            if ok > temp:
                ok = temp

    minng = 2000000001
    for i in range(1, n+1):
        graph[i].sort(key=lambda x: x[1])
        if minng > graph[i][0][1]:
            minng = graph[i][0][1]

        if len(graph[i]) >= 2:
            temp = graph[i][0][1] + graph[i][1][1]
            if minng > temp:
                minng = temp

    print(minng)

if __name__ == "__main__":
    main()

