import sys
from collections import deque

n, m = map(int, sys.stdin.readline().split())
mp = list(map(int, sys.stdin.read().split()))
abc = list(zip(mp, mp, mp))

graph = [[] for i in range(n + 1)]

for a, b, c in abc:
    graph[a].append((b, c))
    graph[b].append((a, c))

ok = float("inf")
minng = 2000000001

for i in range(1, n + 1):
    graph[i].sort(key=lambda x: x[1])
    if ok > graph[i][0][1]:
        ok = graph[i][0][1]

    if len(graph[i]) >= 2:
        temp = graph[i][0][1] + graph[i][1][1]
        if minng > temp:
            minng = temp

print(minng)

def solve(mid):
    q = deque()
    visited = [-1 for _ in range(n + 1)]

    for i in range(1, n + 1):
        if visited[i] != -1:
            continue

        visited[i] = 0
        q.append(i)

        while q:
            v = q.popleft()

            for nv, c in graph[v]:
                if c >= mid and visited[nv] == -1:
                    visited[nv] = visited[v] ^ 1
                    q.append(nv)

    for i in range(1, n + 1):
        for nv, c in graph[i]:
            if visited[i] == visited[nv]:
                return False

    return True

while abs(ok - minng) > 1:
    mid = (ok + minng) // 2
    if solve(mid):
        ok = mid
    else:
        minng = mid

print(ok)

