def solve(mid):
    visited = [-1 for i in range(n+1)]
    que = [1]
    visited[1] = 0
    while que:
        v = que.pop()
        for nv, c in graph[v]:
            if c < mid or visited[nv] != -1:
                continue
            visited[nv] = visited[v] ^ 1
            que.append(nv)
    return all(x != -1 for x in visited)

