    for c, lm in zip(li, lastmodified):
        ans.append(c.upper() if lm>isupper else c.lower())
elif islower > isupper:
    for c, lm in zip(li, lastmodified):
        ans.append(c.lower() if lm>islower else c.upper())
else:
    for c, lm in zip(li, lastmodified):
        ans.append(c.upper() if lm>islower else c.lower())
print(''.join(ans))

